import axios from "axios";
const URL_API = 'http://localhost:8081/api/mercado/v1/facturas';
const URL_API_CLIENTES = 'http://localhost:8081/api/mercado/v1/clientes';

export const consultarFacturas = async () => {
    try {
        console.log('Consultando facturas en:', URL_API);
        const response = await axios.get(`${URL_API}`);
        console.log('Respuesta de facturas:', response.data);
        return response.data;
    } catch (error) {
        console.error('Error consultando facturas:', error);
        throw error;
    }
}

// Función para obtener información completa del cliente por cédula
export const obtenerClientePorCedula = async (cedula) => {
    try {
        console.log('Consultando cliente con cédula:', cedula);
        // Intentar diferentes formas de consultar el cliente
        let response;
        try {
            // Opción 1: Por query parameter
            response = await axios.get(`${URL_API_CLIENTES}?cedula=${cedula}`);
        } catch (e1) {
            try {
                // Opción 2: Por path parameter
                response = await axios.get(`${URL_API_CLIENTES}/cedula/${cedula}`);
            } catch (e2) {
                try {
                    // Opción 3: Obtener todos y filtrar
                    const todosLosClientes = await axios.get(`${URL_API_CLIENTES}`);
                    const cliente = todosLosClientes.data.find(c => c.cedula === cedula);
                    return cliente || null;
                } catch (e3) {
                    console.warn('No se pudo obtener cliente con cédula:', cedula);
                    return null;
                }
            }
        }
        console.log('Cliente encontrado:', response.data);
        return response.data;
    } catch (error) {
        console.warn('Error obteniendo cliente:', error);
        return null;
    }
}

// Función para obtener facturas con información completa del cliente incluyendo género
export const consultarFacturasConClientes = async () => {
    try {
        console.log('Iniciando consulta de facturas con clientes...');
        const facturas = await consultarFacturas();
        console.log('Facturas obtenidas:', facturas);
        
        if (!facturas || facturas.length === 0) {
            console.warn('No se encontraron facturas');
            return [];
        }
        
        // Para cada factura, obtener información completa del cliente
        const facturasConClientes = await Promise.all(
            facturas.map(async (factura) => {
                try {
                    console.log('Procesando factura:', factura);
                    // Intentar con diferentes nombres de campo para la cédula
                    const cedula = factura.cedula || factura.identificacionCliente || factura.cedulaCliente;
                    
                    if (!cedula) {
                        console.warn('Factura sin cédula de cliente:', factura);
                        return {
                            ...factura,
                            clienteCompleto: null
                        };
                    }
                    
                    // Obtener información completa del cliente
                    const cliente = await obtenerClientePorCedula(cedula);
                    console.log('Cliente obtenido para factura:', cliente);
                    
                    return {
                        ...factura,
                        clienteCompleto: cliente
                    };
                } catch (error) {
                    console.warn(`Error procesando factura:`, error);
                    return {
                        ...factura,
                        clienteCompleto: null
                    };
                }
            })
        );
        
        console.log('Facturas con clientes procesadas:', facturasConClientes);
        return facturasConClientes;
    } catch (error) {
        console.error('Error consultando facturas con clientes:', error);
        throw error;
    }
}
